SELECT COUNT(*) FROM answer_records
WHERE user_id = #{userId}

    AND type = #{type}

AND answer_time BETWEEN #{startTime} AND #{endTime}

SELECT u.id as userId, u.nickname as name, u.avatar, SUM(ar.score) as totalScore FROM answer_records ar JOIN user u ON ar.user_id = u.id WHERE ar.answer_time BETWEEN #{startTime} AND #{endTime}
AND ar.type = #{answerType}
GROUP BY u.id, u.nickname, u.avatar ORDER BY totalScore DESC LIMIT #{limit}

SELECT t2.AnswerRecordrank, t2.userId, t2.name, t2.avatar, t2.totalScore FROM ( SELECT CASE WHEN @prev_score = t1.totalScore THEN @rank ELSE @rank := @rank + 1 END as AnswerRecordrank, @prev_score := t1.totalScore as totalScore, t1.userId, t1.name, t1.avatar FROM ( SELECT u.id as userId, u.nickname as name, u.avatar, IFNULL(SUM(ar.score), 0) as totalScore FROM answer_records ar JOIN user u ON ar.user_id = u.id WHERE ar.answer_time BETWEEN #{startTime} AND #{endTime}
AND ar.type = #{answerType}
GROUP BY u.id, u.nickname, u.avatar ORDER BY totalScore DESC ) t1 CROSS JOIN (SELECT @rank := 0, @prev_score := NULL) r ) t2 WHERE t2.userId = #{userId} LIMIT 1
